pub fn tx2_query_tail(proof: &[u8], p: Box<Prepared>, mut a: Accumulator,
    g: [E;29], obs: Observer, geometry: QueryGeometry, mut pending: BatchedWeights)
    -> Result<(Box<Prepared>, Accumulator, BatchedWeights), Error> {
    while a.next < 22 {
        query_values(proof, &p, &mut a, &g, obs, &geometry, Some(&mut pending))?;
    }
    Ok((p, a, pending))
}
